<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require dirname(__DIR__,2).'/vendor/autoload.php';use App\Admin;use App\Security;
Admin::requirePermission('inventory.view');$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::requireCsrf();Admin::requirePermission('inventory.manage');try{$id=(int)($_POST['product_id']??0);$delta=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$note=trim((string)($_POST['note']??''));if(!$id||$delta===false||$delta===0||abs($delta)>100000||mb_strlen($note)<3)throw new RuntimeException('أدخل كمية صحيحة وسبباً واضحاً للتعديل.');$pdo->beginTransaction();$q=$pdo->prepare("SELECT stock_quantity,reserved_quantity FROM products WHERE id=? FOR UPDATE");$q->execute([$id]);$p=$q->fetch();if(!$p)throw new RuntimeException('المنتج غير موجود.');$next=(int)$p['stock_quantity']+$delta;if($next<(int)$p['reserved_quantity']||$next<0)throw new RuntimeException('لا يمكن خفض المخزون إلى أقل من الكمية المحجوزة.');$pdo->prepare("UPDATE products SET stock_quantity=? WHERE id=?")->execute([$next,$id]);$pdo->prepare("INSERT INTO inventory_movements(product_id,user_id,movement_type,quantity,note) VALUES(?,?, 'adjustment',?,?)")->execute([$id,$_SESSION['admin_user']['id'],$delta,$note]);$pdo->commit();Admin::audit('inventory.adjust','product',$id,['delta'=>$delta]);header('Location: inventory.php?updated=1');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'تعذر تعديل المخزون.';}}
$products=$pdo->query("SELECT id,name,sku,stock_quantity,reserved_quantity,low_stock_threshold FROM products ORDER BY name")->fetchAll();$moves=$pdo->query("SELECT m.*,p.name product_name,u.name user_name FROM inventory_movements m JOIN products p ON p.id=m.product_id LEFT JOIN users u ON u.id=m.user_id ORDER BY m.id DESC LIMIT 100")->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>المخزون | الفخامة</title><link rel="stylesheet" href="../assets/css/store.css"><style>.wrap{max-width:1150px;margin:30px auto;padding:0 16px}.panel{background:#111;border:1px solid #49371c;border-radius:14px;padding:18px;margin:16px 0}.fields{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.fields label{display:block}.fields input,.fields select{width:100%;padding:10px;background:#080808;color:white;border:1px solid #49371c;border-radius:8px;font:inherit}.table{width:100%;border-collapse:collapse}.table td,.table th{text-align:right;padding:10px;border-bottom:1px solid #342718}.scroll{overflow:auto}.table{min-width:720px}@media(max-width:700px){.fields{grid-template-columns:1fr 1fr}}</style></head><body><main class="wrap"><a class="text-link" href="index.php">← لوحة التحكم</a><h1>إدارة المخزون</h1><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['updated'])):?><div class="notice">تم تحديث المخزون وتسجيل الحركة.</div><?php endif;?><section class="panel"><h2>تسوية المخزون</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><div class="fields"><label>المنتج<select name="product_id" required><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>"><?=e($p['name'])?> (<?=e($p['sku'])?>)</option><?php endforeach;?></select></label><label>فرق الكمية (+ إضافة / - خصم)<input type="number" name="quantity" required min="-100000" max="100000"></label><label>سبب التعديل<input name="note" required minlength="3" maxlength="500"></label><label><span>&nbsp;</span><button class="btn btn-gold">تسجيل الحركة</button></label></div></form></section><section class="panel"><h2>أرصدة المنتجات</h2><div class="scroll"><table class="table"><thead><tr><th>المنتج</th><th>SKU</th><th>المخزون الفعلي</th><th>محجوز</th><th>متاح للبيع</th><th>تنبيه عند</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['sku'])?></td><td><?=(int)$p['stock_quantity']?></td><td><?=(int)$p['reserved_quantity']?></td><td><?=(int)$p['stock_quantity']-(int)$p['reserved_quantity']?></td><td><?=(int)$p['low_stock_threshold']?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2>آخر حركات المخزون</h2><div class="scroll"><table class="table"><thead><tr><th>الوقت</th><th>المنتج</th><th>الحركة</th><th>الكمية</th><th>الموظف</th><th>ملاحظة</th></tr></thead><tbody><?php foreach($moves as $m):?><tr><td><?=e($m['created_at'])?></td><td><?=e($m['product_name'])?></td><td><?=e($m['movement_type'])?></td><td><?=(int)$m['quantity']?></td><td><?=e($m['user_name']??'النظام')?></td><td><?=e($m['note']??'')?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>